-- P1b publication proof: all identities, administrative replacement and failures roll back.
begin;
create function pg_temp.pu_id(n integer) returns uuid language sql immutable as $$select ('f9200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.pu_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.pu_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected SQLSTATE %',state;end$$;
create function pg_temp.pu_doc() returns jsonb language sql as $$select jsonb_build_object('rulesVersion','FIBA_2024','periods',4,'participants',(select jsonb_agg(jsonb_build_object('rosterEntryId',pg_temp.pu_id(100+n),'side',case when n<=5 or n=11 then 'home' else 'away' end,'jersey',case when n=11 then '9' when n%5=1 then '0' when n%5=2 then '00' else (n%5+2)::text end,'played',n<>11,'starter',n<>11) order by n) from generate_series(1,11) n),'staff',jsonb_build_object('home',jsonb_build_object('captainRosterEntryId',pg_temp.pu_id(101),'coachStaffEntryId',null,'assistantStaffEntryId',null),'away',jsonb_build_object('captainRosterEntryId',pg_temp.pu_id(106),'coachStaffEntryId',null,'assistantStaffEntryId',null)),'events',jsonb_build_array(jsonb_build_object('id',pg_temp.pu_id(400),'side','home','period',4,'target','0','code','2')))$$;
create function pg_temp.pu_command(n integer default 1) returns jsonb language sql as $$select jsonb_build_object('requestId',pg_temp.pu_id(500+n),'gameId',pg_temp.pu_id(8),'gameVersion',1,'basePublicationVersion',0,'source',jsonb_build_object('kind','sheet','baseSheetVersion',0,'document',pg_temp.pu_doc()),'reason','','fallback',false)$$;
create function pg_temp.pu_revision(n integer default 3) returns jsonb language sql as $$select pg_temp.pu_command(n)||jsonb_build_object('gameVersion',2,'basePublicationVersion',1,'source',jsonb_build_object('kind','sheet','baseSheetVersion',1,'document',jsonb_set(pg_temp.pu_doc(),'{events,0,code}','"3"')),'reason','Correção da cesta após conferência da súmula.')$$;
grant execute on function pg_temp.pu_id(integer),pg_temp.pu_assert(boolean,text),pg_temp.pu_error(text,text),pg_temp.pu_doc(),pg_temp.pu_command(integer),pg_temp.pu_revision(integer) to anon,authenticated,service_role;
delete from public.admin_access;
insert into auth.users(id) values(pg_temp.pu_id(98)),(pg_temp.pu_id(99));
insert into public.admin_access(user_id) values(pg_temp.pu_id(98));
insert into public.championships(id,name) values(pg_temp.pu_id(1),'Publication fixture');
insert into public.seasons(id,championship_id,year) values(pg_temp.pu_id(2),pg_temp.pu_id(1),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.pu_id(3),pg_temp.pu_id(2),'masculino','Adulto');
insert into public.teams(id,name) values(pg_temp.pu_id(4),'Global team');
insert into public.registrations(id,dispute_id,team_id,name) values(pg_temp.pu_id(5),pg_temp.pu_id(3),pg_temp.pu_id(4),'Home'),(pg_temp.pu_id(6),pg_temp.pu_id(3),pg_temp.pu_id(4),'Away');
insert into public.games(id,dispute_id,home_registration_id,away_registration_id) values(pg_temp.pu_id(8),pg_temp.pu_id(3),pg_temp.pu_id(5),pg_temp.pu_id(6)),(pg_temp.pu_id(9),pg_temp.pu_id(3),pg_temp.pu_id(5),pg_temp.pu_id(6));
insert into public.persons(id,name) select pg_temp.pu_id(200+n),'Player '||n from generate_series(1,11) n;
insert into private.athletes(person_id,sex,birth_date,federation_registration) select pg_temp.pu_id(200+n),'male','1990-01-01'::date,lpad(n::text,6,'0') from generate_series(1,11) n;
insert into public.roster_entries(id,registration_id,dispute_id,person_id,jersey) select pg_temp.pu_id(100+n),case when n<=5 or n=11 then pg_temp.pu_id(5) else pg_temp.pu_id(6) end,pg_temp.pu_id(3),pg_temp.pu_id(200+n),case when n=11 then '9' when n%5=1 then '0' when n%5=2 then '00' else (n%5+2)::text end from generate_series(1,11) n;
set local role anon;
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(8)) is null,'no public draft');
select pg_temp.pu_error('select public.publish_sheet_game(pg_temp.pu_command())','42501');
set local role authenticated;
set local request.jwt.claim.sub='f9200000-0000-4000-8000-000000000099';
select pg_temp.pu_error('select public.publish_sheet_game(pg_temp.pu_command())','PT403');
select pg_temp.pu_error('select public.get_game_publication_state(pg_temp.pu_id(8))','PT403');
set local request.jwt.claim.sub='f9200000-0000-4000-8000-000000000098';
select pg_temp.pu_assert((public.publish_sheet_game(pg_temp.pu_command())->>'version')::integer=1,'first publication');
select pg_temp.pu_assert((public.publish_sheet_game(pg_temp.pu_command())->>'version')::integer=1,'lost response replay keeps publication');
select pg_temp.pu_assert(public.get_game_sheet(pg_temp.pu_id(8))->'confirmed'='true','confirmation persisted atomically');
select pg_temp.pu_assert(public.get_game(pg_temp.pu_id(8))->>'state'='finished','game is finished');
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(8))->'facts'->'teams'->'home'->'points'='2','public facts derived');
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(9)) is null,'other game remains private');
select pg_temp.pu_assert(not(public.get_public_game(pg_temp.pu_id(8))::text~'"(sex|birthDate|birth_date|federationRegistration|federation_registration|storagePath|reason|actorId|createdBy)"'),'private fields absent');
select pg_temp.pu_error($q$select public.publish_sheet_game(pg_temp.pu_command(2))$q$,'PT409');
select pg_temp.pu_error($q$select public.publish_sheet_game(pg_temp.pu_command(2))$q$,'PT409');
select pg_temp.pu_error($q$select public.publish_sheet_game(jsonb_set(pg_temp.pu_command(),'{reason}','"different intent"'))$q$,'PT409');
select pg_temp.pu_error($q$select public.publish_sheet_game(jsonb_set(pg_temp.pu_revision(),'{reason}','""'))$q$,'PT400');
select pg_temp.pu_error($q$select public.publish_sheet_game(jsonb_set(pg_temp.pu_revision(4),'{reason}',to_jsonb(repeat(E'\n',10))))$q$,'PT400');
reset role;
-- Force a failure after the sheet save and verify all changes roll back together.
create function pg_temp.pu_fail() returns trigger language plpgsql as $$begin raise exception 'fixture publication failure';end$$;
create trigger publication_fixture_failure before update on public.published_games for each row when(new.version=2) execute function pg_temp.pu_fail();
set local role authenticated;
select pg_temp.pu_error('select public.publish_sheet_game(pg_temp.pu_revision())','P0001');
select pg_temp.pu_assert(public.get_game_sheet(pg_temp.pu_id(8))->'version'='1' and public.get_game(pg_temp.pu_id(8))->'version'='2','failed publication preserves sheet and game versions');
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(8))->'version'='1','previous public version intact');
reset role;
drop trigger publication_fixture_failure on public.published_games;
set local role authenticated;
select pg_temp.pu_assert(public.publish_sheet_game(pg_temp.pu_revision())->'version'='2','same failed command can be retried');
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(8))->'facts'->'teams'->'home'->'points'='3','correction replaces public facts');
select pg_temp.pu_assert(jsonb_array_length(public.get_game_publication_state(pg_temp.pu_id(8))->'history')=2,'previous versions retained');
select pg_temp.pu_assert(public.get_game_publication_version(pg_temp.pu_id(8),1)->'snapshot'->'facts'->'teams'->'home'->'points'='2','old snapshot and facts remain available administratively');
select pg_temp.pu_error($q$select public.save_game_sheet(jsonb_build_object('requestId',pg_temp.pu_id(700),'gameId',pg_temp.pu_id(8),'gameVersion',3,'baseVersion',2,'document',jsonb_set(pg_temp.pu_doc(),'{participants,10,jersey}','"8"'),'confirm',false,'reason','Correção com camisa diferente.'))$q$,'PT409');
select pg_temp.pu_error($q$select public.save_game_sheet(jsonb_build_object('requestId',pg_temp.pu_id(701),'gameId',pg_temp.pu_id(8),'gameVersion',3,'baseVersion',2,'document',pg_temp.pu_doc(),'confirm',false,'reason',''))$q$,'PT400');
select pg_temp.pu_assert(public.save_game_sheet(jsonb_build_object('requestId',pg_temp.pu_id(702),'gameId',pg_temp.pu_id(8),'gameVersion',3,'baseVersion',2,'document',jsonb_set(jsonb_set(pg_temp.pu_doc(),'{events,0,code}','"3"'),'{participants,10,played}','true'),'confirm',false,'reason','Atleta também participou sem ações.'))->'confirmed'='true','participation correction remains a confirmed source draft');
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(8))->'facts'->'players'->10->'played'='false','editing confirmed source does not publish draft');
select pg_temp.pu_error('select * from private.game_publication_versions','42501');
select pg_temp.pu_error('delete from public.published_games','42501');
set local role anon;
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(8))->'version'='2','anonymous reads only actual published projection');
select pg_temp.pu_error('select public.get_game_publication_state(pg_temp.pu_id(8))','42501');
select pg_temp.pu_error('select public.get_game_publication_version(pg_temp.pu_id(8),1)','42501');
reset role;
-- Presence-only G3 metadata fixture; no blob or PDF fact publication is claimed.
insert into public.pdf_sources(id,dispute_id,filename,sha256,byte_size,page_count,parsed,created_by,ready,version) values(pg_temp.pu_id(800),pg_temp.pu_id(3),'Fixture.pdf',repeat('a',64),10,1,'{}',pg_temp.pu_id(98),true,2);
insert into public.pdf_reviews(source_id,dispute_id,game_id,document,saved_by) values(pg_temp.pu_id(800),pg_temp.pu_id(3),pg_temp.pu_id(9),'{}',pg_temp.pu_id(98));
set local role authenticated;
select pg_temp.pu_error($q$select public.publish_sheet_game(jsonb_set(jsonb_set(pg_temp.pu_command(10),'{gameId}',to_jsonb(pg_temp.pu_id(9))),'{source,baseSheetVersion}','0'))$q$,'PT400');
select pg_temp.pu_assert(public.publish_sheet_game(jsonb_set(pg_temp.pu_command(11),'{gameId}',to_jsonb(pg_temp.pu_id(9)))||jsonb_build_object('fallback',true,'reason','Escolha explícita da súmula manual em vez do PDF.'))->'version'='1','manual fallback explicit and scoped to selected game');
reset role;
select pg_temp.pu_assert((select count(*) from private.game_publication_versions where game_id=pg_temp.pu_id(8))=2,'source-only draft creates no publication history');
select pg_temp.pu_assert((select count(*) from private.game_publication_entries where game_id=pg_temp.pu_id(8) and version=1)=11,'historical identities preserved by FKs');
update public.admin_access set enabled=false;
set local role authenticated;
select pg_temp.pu_error('select public.publish_sheet_game(pg_temp.pu_command())','PT403');
select pg_temp.pu_error('select public.get_game_publication_state(pg_temp.pu_id(8))','PT403');
set local role service_role;
select pg_temp.pu_error('select public.publish_sheet_game(pg_temp.pu_command())','42501');
reset role;
rollback;
